// Tree views and the nodes in them. A tree view has a root node that is not shown and that all other nodes are in.

#include "handle_check.h"
#include "gui_internal.hpp"
#include "memory.h"
#include "runtime_internal.h"

namespace bb::gui {
	static node* need_node(int handle, const char* what)
	{
		node* n = node_of(handle);
		if (!n) {
			char message[128];
			snprintf(message, sizeof(message), "%s: the tree view node does not exist.", what);
			gui_error(message);
		}
		return n;
	}

	static int new_node(int tree, int parent, const char* text, int icon)
	{
		node* n   = new node();
		n->used   = true;
		n->tree   = tree;
		n->parent = parent;
		n->text   = copy_string(text);
		n->icon   = icon;
		nodes.push(n);
		return int(nodes.size) + node_base;
	}

	void free_node(int handle)
	{
		node* n = node_of(handle);
		if (!n) {
			return;
		}
		while (n->kids.size) {
			free_node(n->kids[n->kids.size - 1]);
		}
		if (gadget* tree = gadget_of(n->tree)) {
			if (tree->selected_node == handle) {
				tree->selected_node = 0;
			}
			if (tree->root == handle) {
				tree->root = 0;
			}
		}
		if (node* parent = node_of(n->parent)) {
			for (uint32_t k = 0; k < parent->kids.size; k++) {
				if (parent->kids[k] == handle) {
					for (uint32_t m = k + 1; m < parent->kids.size; m++) {
						parent->kids[m - 1] = parent->kids[m];
					}
					parent->kids.size--;
					break;
				}
			}
		}
		bb_free(n->text);
		n->text = nullptr;
		n->kids.release();
		n->used = false;
		dirty();
	}

	// How many nodes are shown: the ones that have no collapsed node above them.
	static int count_shown(int handle)
	{
		node* n = node_of(handle);
		int   count = 0;
		if (n && (n->expanded || !n->parent)) {
			for (uint32_t i = 0; i < n->kids.size; i++) {
				count += 1 + count_shown(n->kids[i]);
			}
		}
		return count;
	}

	int count_visible_nodes(gadget const& g)
	{
		return count_shown(g.root);
	}

	void select_tree_node(int handle, bool user)
	{
		node* n = node_of(handle);
		if (!n || !n->parent) {
			return; // The root is not a thing that can be selected.
		}
		gadget* tree = gadget_of(n->tree);
		if (!tree) {
			return;
		}
		// What is selected is shown: the nodes it is in are opened.
		for (node* p = node_of(n->parent); p; p = node_of(p->parent)) {
			p->expanded = true;
		}
		if (tree->selected_node != handle) {
			tree->selected_node = handle;
			post_action(n->tree, 0);
		}
		(void)user;
		dirty();
	}

	void expand_node(int handle, bool expand)
	{
		node* n = node_of(handle);
		if (!n || !n->parent) {
			return;
		}
		n->expanded = expand && n->kids.size;
		if (!n->expanded) {
			// Closing a node that has the selected one in it moves the selection to the node.
			gadget* tree = gadget_of(n->tree);
			for (node* p = tree ? node_of(tree->selected_node) : nullptr; p; p = node_of(p->parent)) {
				if (node_of(p->parent) == n) {
					tree->selected_node = handle;
					post_action(n->tree, 0);
					break;
				}
			}
		}
		dirty();
	}
} // namespace bb::gui

using namespace bb::gui;

extern "C" {

int32_t bb_create_tree_view(int32_t x, int32_t y, int32_t w, int32_t h, int32_t group, int32_t style)
{
	int     handle = make_gadget(K_TREEVIEW, style, group, x, y, w, h, "CreateTreeView");
	gadget* g      = gadget_of(handle);
	g->root        = new_node(handle, 0, "", -1);
	return handle;
}

int32_t bb_tree_view_root(int32_t handle)
{
	return need_kind(handle, K_TREEVIEW, "TreeViewRoot")->root;
}

int32_t bb_selected_tree_view_node(int32_t handle)
{
	return need_kind(handle, K_TREEVIEW, "SelectedTreeViewNode")->selected_node;
}

int32_t bb_count_tree_view_nodes(int32_t handle)
{
	return int32_t(need_node(handle, "CountTreeViewNodes")->kids.size);
}

int32_t bb_add_tree_view_node(const char* text, int32_t parent, int32_t icon)
{
	node* p = need_node(parent, "AddTreeViewNode");
	int   h = new_node(p->tree, parent, text, icon);
	p->kids.push(h);
	dirty();
	return h;
}

int32_t bb_insert_tree_view_node(int32_t index, const char* text, int32_t parent, int32_t icon)
{
	node* p = need_node(parent, "InsertTreeViewNode");
	int   h = new_node(p->tree, parent, text, icon);
	// What the original does: the node goes after the child that is at index - 1, and index 0 or less is the first.
	int at = index <= 0 ? 0 : (index >= int(p->kids.size) ? int(p->kids.size) : index);
	p->kids.push(h);
	for (int i = int(p->kids.size) - 1; i > at; i--) {
		p->kids[uint32_t(i)] = p->kids[uint32_t(i - 1)];
	}
	p->kids[uint32_t(at)] = h;
	dirty();
	return h;
}

void bb_modify_tree_view_node(int32_t handle, const char* text, int32_t icon)
{
	node* n = need_node(handle, "ModifyTreeViewNode");
	if (n->parent) {
		set_string(n->text, text);
		if (icon > -1) {
			n->icon = icon;
		}
	}
	dirty();
}

void bb_select_tree_view_node(int32_t handle)
{
	need_node(handle, "SelectTreeViewNode");
	select_tree_node(handle, false);
}

void bb_expand_tree_view_node(int32_t handle)
{
	need_node(handle, "ExpandTreeViewNode");
	expand_node(handle, true);
}

void bb_collapse_tree_view_node(int32_t handle)
{
	need_node(handle, "CollapseTreeViewNode");
	expand_node(handle, false);
}

void bb_free_tree_view_node(int32_t handle)
{
	if (!handle) {
		BB_DEBUG_HANDLE_MISSING("FreeTreeViewNode", "tree view node", handle);
		return;
	}
	node* n = need_node(handle, "FreeTreeViewNode");
	if (!n->parent) {
		// The root is kept, what is in it goes.
		while (n->kids.size) {
			free_node(n->kids[n->kids.size - 1]);
		}
		return;
	}
	free_node(handle);
}

const char* bb_tree_view_node_text(int32_t handle)
{
	return string_result(need_node(handle, "TreeViewNodeText")->text);
}

int32_t bb_create_text_area(int32_t x, int32_t y, int32_t w, int32_t h, int32_t group, int32_t style)
{
	int handle = make_gadget(K_TEXTAREA, style, group, x, y, w, h, "CreateTextArea");
	set_string(gadget_of(handle)->text, "");
	return handle;
}
}
